-- Initial PostgreSQL baseline as it existed immediately before reading receive-time tracking.
-- Existing installations may be baselined at version 1 only after an operator verifies this schema.
create table app_user (clinic_id uuid, id uuid not null, display_name varchar(255) not null, role varchar(255) not null, primary key (id), constraint app_user_role_check check (role in ('DOCTOR','PATIENT','CAREGIVER')));
create table appointment (booked_at timestamp(6) with time zone not null, cancelled_at timestamp(6) with time zone, starts_at timestamp(6) with time zone not null, booked_by uuid not null, clinic_id uuid not null, id uuid not null, patient_id uuid not null, slot_key varchar(100) unique, reason_enc varchar(1024), status varchar(255) not null check (status in ('BOOKED','CANCELLED')), primary key (id));
create table approved_answer (approved_at timestamp(6) with time zone not null, retired_at timestamp(6) with time zone, approved_by_id uuid not null, clinic_id uuid not null, id uuid not null, title varchar(200) not null, primary key (id));
create table approved_answer_text (language varchar(8) not null, answer_id uuid not null, text varchar(2000) not null, primary key (language, answer_id));
create table approved_answer_trigger (position integer not null, answer_id uuid not null, phrase varchar(200) not null, primary key (position, answer_id));
create table audit_log (at timestamp(6) with time zone not null, id bigint generated by default as identity, actor_id uuid not null, patient_id uuid not null, action varchar(255) not null check (action in ('VIEWED_RECORD','CALLED_ABOUT_REPLY','OVERRODE_SAFETY_FINDING','VIEWED_SUMMARY','VIEWED_MEDICATIONS','VIEWED_INTAKE','VIEWED_PREVISIT','VIEWED_READINGS')), actor_label varchar(255) not null, primary key (id));
create table caregiver_link (consented_at timestamp(6) with time zone not null, revoked_at timestamp(6) with time zone, caregiver_id uuid not null, id uuid not null, patient_id uuid not null, scope varchar(255) not null check (scope in ('SUMMARY','SUMMARY_AND_ALERTS')), primary key (id));
create table check_in (day_number integer not null, due_date date not null, fasting boolean not null, sent_at timestamp(6) with time zone, encounter_id uuid, id uuid not null, patient_id uuid not null, status varchar(255) not null check (status in ('PENDING','SENT','ANSWERED','FAILED')), primary key (id));
create table clinic (id uuid not null, name varchar(255) not null, primary key (id));
create table device_link (linked_at timestamp(6) with time zone not null, linked_by uuid not null, patient_id uuid not null, device_id varchar(200) not null, primary key (device_id));
create table encounter (checked_revision integer, fasting boolean not null, follow_up_weeks float(53), open_critical_findings integer not null, revision integer not null, finalised_at timestamp(6) with time zone, started_at timestamp(6) with time zone, doctor_id uuid not null, id uuid not null, patient_id uuid not null, diagnosis_enc varchar(4096), plan_enc varchar(8192), notes_enc varchar(16384), follow_up varchar(255), status varchar(255) not null check (status in ('DRAFT','FINAL')), primary key (id), check (status <> 'FINAL' or open_critical_findings = 0));
create table encounter_prescription (as_needed boolean, line_no integer not null, strength_mg float(53), times_per_day integer, units_per_dose float(53), encounter_id uuid not null, raw varchar(500), name varchar(255), times_of_day varchar(255), timing varchar(255), primary key (line_no, encounter_id));
create table intake_session (completed_at timestamp(6) with time zone, started_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, patient_id uuid not null, report_enc varchar(200000), transcript_enc varchar(200000) not null, primary key (id));
create table invite (expires_at timestamp(6) with time zone not null, used_at timestamp(6) with time zone, clinic_id uuid, created_by uuid not null, id uuid not null, patient_id uuid, used_by uuid, code_hash varchar(64) not null unique, kind varchar(255) not null, scope varchar(255) check (scope in ('SUMMARY','SUMMARY_AND_ALERTS')), primary key (id), constraint invite_kind_check check (kind in ('PATIENT_ACCOUNT','CAREGIVER','DOCTOR')));
create table medication_item (added_at timestamp(6) with time zone not null, stopped_at timestamp(6) with time zone, added_by uuid not null, id uuid not null, patient_id uuid not null, name_enc varchar(1024) not null, source_enc varchar(1024), added_by_role varchar(255) not null, kind varchar(255) not null check (kind in ('MEDICINE','HERB')), primary key (id), constraint medication_item_added_by_role_check check (added_by_role in ('DOCTOR','PATIENT','CAREGIVER')));
create table outbound_message (delivered boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, patient_id uuid not null, error varchar(2000), text_enc varchar(16384) not null, channel varchar(255) not null, kind varchar(255) not null, provider_id varchar(255), primary key (id));
create table patient (follow_up_start date, pregnant boolean not null, account_id uuid, clinic_id uuid not null, graph_id uuid not null unique, id uuid not null, phone_index varchar(64), ic_number_enc varchar(512), phone_enc varchar(512), allergies_enc varchar(2048), full_name varchar(255) not null, preferred_language varchar(255) not null, primary key (id));
create table patient_reply (missed_dose boolean not null, handled_at timestamp(6) with time zone, received_at timestamp(6) with time zone not null, answered_with uuid, handled_by uuid, id uuid not null, patient_id uuid not null, text_enc varchar(4096) not null, level varchar(255) not null check (level in ('RED','WATCH','REVIEW','OK')), matched varchar(255), primary key (id));
create table reading (diastolic integer, glucose float(53), systolic integer, handled_at timestamp(6) with time zone, measured_at timestamp(6) with time zone not null, handled_by uuid, id uuid not null, patient_id uuid not null, source varchar(20) not null, description varchar(100) not null, kind varchar(255) not null check (kind in ('BLOOD_PRESSURE','GLUCOSE')), level varchar(255) not null check (level in ('RED','WATCH','REVIEW','OK')), primary key (id));
create table safety_finding (finding_no integer, overridden_at timestamp(6) with time zone, encounter_id uuid not null, id uuid not null, overridden_by uuid, detail varchar(1000) not null, override_reason varchar(1000), check_name varchar(255) not null, severity varchar(255) not null, primary key (id));
create table visit_summary (created_at timestamp(6) with time zone not null, encounter_id uuid not null, id uuid not null, patient_id uuid not null, needs_doctor varchar(2000), text_enc varchar(16384) not null, language varchar(255) not null, primary key (id));
create index IDX2lyh5p6h5m9cyxcos4960wory on audit_log (patient_id);
create index IDXrqcfgq5knyoih3fke2bf59sli on patient (phone_index);
